use std::fs;
use std::path::Path;

fn main() {
    println!("cargo:rustc-check-cfg=cfg(mrml_modern)");

    let lock_path = Path::new("Cargo.lock");
    let Ok(lock) = fs::read_to_string(lock_path) else {
        return;
    };

    if mrml_major_version(&lock).is_some_and(|major| major >= 5) {
        println!("cargo:rustc-cfg=mrml_modern");
    }
}

fn mrml_major_version(lock: &str) -> Option<u64> {
    let mut in_mrml_package = false;

    for line in lock.lines() {
        match line {
            "[[package]]" => in_mrml_package = false,
            "name = \"mrml\"" => in_mrml_package = true,
            _ if in_mrml_package && line.starts_with("version = ") => {
                let version = line.trim_start_matches("version = ").trim_matches('"');
                return version.split('.').next()?.parse().ok();
            }
            _ => {}
        }
    }

    None
}

