#[derive(NifStruct)]
#[module = "Mjml.RenderOptions"]
pub struct Options {
    pub keep_comments: bool,
    pub social_icon_path: Option<String>,
}

#[rustler::nif]
pub fn to_html<'a>(env: Env<'a>, mjml: String, render_options: Options) -> NifResult<Term<'a>> {
    return match mrml::parse(&mjml) {
        Ok(root) => {
            return match render(root, render_options) {
                Ok(content) => Ok((atoms::ok(), content).encode(env)),
                Err(error) => Ok((atoms::error(), error.to_string()).encode(env)),
            };
        }
        Err(error) => Ok((atoms::error(), error.to_string()).encode(env)),
    };
}

#[cfg(not(mrml_modern))]
fn render(
    root: mrml::mjml::MJML,
    render_options: Options,
) -> Result<String, mrml::prelude::render::Error> {
    let options = mrml::prelude::render::Options {
        disable_comments: !render_options.keep_comments,
        social_icon_origin: render_options.social_icon_path,
    };

    root.render(&options)
}

#[cfg(mrml_modern)]
fn render(
    root: mrml::prelude::parser::ParseOutput<mrml::mjml::Mjml>,
    render_options: Options,
) -> Result<String, mrml::prelude::render::Error> {
    let options = mrml::prelude::render::RenderOptions {
        disable_comments: !render_options.keep_comments,
        social_icon_origin: render_options.social_icon_path.map(Cow::Owned),
        ..Default::default()
    };

    root.element.render(&options)
}

